let Vdelete : Fin n → Ω → ℝ :=
  fun (i : Fin n) (ω : Ω) =>
    Real.sqrt (∑ j ∈ Finset.univ.erase i, (ξ j ω) ^ 2)

let Hdelete : Fin n → Ω → ℝ :=
  fun (i : Fin n) (ω : Ω) =>
    (1 + Vdelete i ω) * (Real.sqrt (n : ℝ) + z * Cdelete i ω)

let κ : Fin n → ℝ :=
  fun i : Fin n => 4 * Real.sqrt (n : ℝ) *
    ((∫ ω, H ω ∂ν) + (∫ ω, Hdelete i ω ∂ν))
